CREATE TABLE IF NOT EXISTS market_data.statis_index(    created_at                TIMESTAMP   NOT NULL DEFAULT now(), -- Thời gian tạo    updated_at                TIMESTAMP   NOT NULL DEFAULT now(), -- Thời gian cập nhật    ------------------------------------------------------------------------------------------    ticker                    VARCHAR(10) NOT NULL,               -- mã chứng khóa    trading_date              DATE        NOT NULL,    ----------    open_price                INT,    highest_price             INT,    lowest_price              INT,    closed_price              INT,    average_price             DOUBLE PRECISION,    -------------------------------------------    total_shares_traded       BIGINT,    total_values_traded       BIGINT,    total_shares_traded_mt    BIGINT,    total_values_traded_mt    BIGINT,    total_shares_traded_pt    BIGINT,    total_values_traded_pt    BIGINT,    -------------------------------------------    shares_outstanding        BIGINT,    change_price_value        BIGINT,    change_price_percentage   DOUBLE PRECISION,    -------------------------------------------    total_foreign_buy_volume  BIGINT,    total_foreign_sell_volume BIGINT,    total_foreign_buy_value   BIGINT,    total_foreign_sell_value  BIGINT,    total_foreign_net_value   BIGINT,    total_foreign_net_volume  BIGINT,    PRIMARY KEY (ticker, trading_date))